create schema if not exists menus;
create table if not exists menus.menus(id uuid primary key default gen_random_uuid(),organization_id uuid references core.organizations(id),unit_id uuid references core.units(id),prospect_id uuid references core.prospects(id),slug text not null unique,name text not null,description text not null default '',cover_image_url text,logo_image_url text,current_publication_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(unit_id is not null or prospect_id is not null),unique(unit_id));
create table if not exists menus.versions(id uuid primary key default gen_random_uuid(),menu_id uuid not null references menus.menus(id) on delete cascade,version integer not null,snapshot jsonb not null,reason text not null,created_at timestamptz not null default now(),unique(menu_id,version));
alter table menus.menus add constraint menus_current_publication_fk foreign key(current_publication_id) references menus.versions(id) on delete set null;
